xy_to_id={(i%W, i//W):i for i,_ in plots}

def terrain_name(t):
    if t=='TERRAIN_COAST': return 'COAST'
    if t=='TERRAIN_OCEAN': return 'OCEAN'
    if t=='TERRAIN_GRASS': return 'GRASS'
    if t=='TERRAIN_PLAINS': return 'PLAINS'
    if 'MOUNTAIN' in t: return 'MOUNTAIN'
    return 'UNKNOWN'

def river_edges_for(x,y):
    i=xy_to_id.get((x,y))
    ne,w,nw=river3.get(i,(0,0,0))
    edges=set()
    if ne: edges.add(1)
    if nw: edges.add(2)
    if w: edges.add(3)
    ex,ey=get_neighbor_at_direction(x,y,0)
    j=xy_to_id.get((ex,ey))
    if j is not None and river3.get(j,(0,0,0))[1]: edges.add(0)
    swx,swy=get_neighbor_at_direction(x,y,4)
    j=xy_to_id.get((swx,swy))
    if j is not None and river3.get(j,(0,0,0))[0]: edges.add(4)
    sex,sey=get_neighbor_at_direction(x,y,5)
    j=xy_to_id.get((sex,sey))
    if j is not None and river3.get(j,(0,0,0))[2]: edges.add(5)
    return sorted(edges)

tiles={}
for rid,terr in plots:
    x,y=rid%W, rid//W
    feature=feat.get(rid)
    tiles[(x,y)] = Tile(
        x=x,y=y,
        terrain=terrain_name(terr),
        feature=feature,
        is_hills=False,
        is_floodplains=bool(feature and 'FLOODPLAINS' in feature),
        river_edges=river_edges_for(x,y),
        resource=None,
        resource_type=None,
        improvement=None,
    )

adj_calc=get_adjacency_calculator(tiles)

# Candidates
cc_candidates=[xy for xy,t in tiles.items() if (not t.is_water and not t.is_mountain and t.feature!='FEATURE_ICE')]

# Focused combos (3 specialty max at pop 9)
DT_C=DistrictType.CAMPUS
DT_CH=DistrictType.COMMERCIAL_HUB
DT_H=DistrictType.HARBOR
DT_IZ=DistrictType.INDUSTRIAL_ZONE
combos=[
    (DT_C, DT_CH, DT_IZ),
    (DT_C, DT_H, DT_IZ),
    (DT_CH, DT_H, DT_IZ),
    (DT_C, DT_CH, DT_H),
]

SUPPORT_DEFAULT=DistrictType.NEIGHBORHOOD
SUPPORT_NEAR_IZ=[DistrictType.DAM, DistrictType.AQUEDUCT, DistrictType.CANAL, DistrictType.NEIGHBORHOOD]


def fill_supports(rules, cc, placements):
    iz=None
    for pos,dt in placements.items():
        if dt==DT_IZ:
            iz=pos
            break

    area=[cc]+[p for p in get_tiles_in_range(cc[0],cc[1],3) if p in tiles]
    for (x,y) in area:
        if (x,y) in placements:
            continue

        candidates=[SUPPORT_DEFAULT]
        if iz and hex_distance(x,y,iz[0],iz[1])==1:
            candidates=SUPPORT_NEAR_IZ

        for dt in candidates:
            if rules.validate_placement(dt,x,y,placements).valid:
                placements[(x,y)]=dt
                break


def placement_score_for_single(rules, cc, dt, pos):
    base={cc: DistrictType.CITY_CENTER, pos: dt}
    # fill just neighbors of pos to estimate potential
    tmp=dict(base)
    iz = pos if dt==DT_IZ else None
    for nx,ny in get_neighbors(pos[0],pos[1]):
        if (nx,ny) not in tiles or (nx,ny) in tmp:
            continue
        # must still be within 3 of cc
        if hex_distance(nx,ny,cc[0],cc[1])>3:
            continue
        cand=[SUPPORT_DEFAULT]
        if iz and hex_distance(nx,ny,iz[0],iz[1])==1:
            cand=SUPPORT_NEAR_IZ
        for sdt in cand:
            if rules.validate_placement(sdt,nx,ny,tmp).valid:
                tmp[(nx,ny)] = sdt
                break
    total,_=adj_calc.calculate_total_adjacency(tmp)
    return total


def build_and_score(cc, specialty_map):
    rules=get_placement_rules(tiles, cc, POP)
    placements={cc: DistrictType.CITY_CENTER}
    # place specialty
    for dt,pos in specialty_map.items():
        if not rules.validate_placement(dt,pos[0],pos[1],placements).valid:
            return None
        placements[pos]=dt

    fill_supports(rules, cc, placements)

    total,_=adj_calc.calculate_total_adjacency(placements)
    return total, placements

start=time.time()
best_total=-1
best_cc=None
best_specialty=None
best_placements=None

evals=0
for cc in cc_candidates:
    rules=get_placement_rules(tiles, cc, POP)
    base={cc: DistrictType.CITY_CENTER}
    area=[cc]+[p for p in get_tiles_in_range(cc[0],cc[1],3) if p in tiles]

    valid={}
    for dt in {d for combo in combos for d in combo}:
        poss=[]
        for p in area:
            if rules.validate_placement(dt,p[0],p[1],base).valid:
                poss.append(p)
        scored=[(placement_score_for_single(rules,cc,dt,p),p) for p in poss]
        scored.sort(reverse=True)
        valid[dt]=[p for _,p in scored[:TOP_K]]

    for combo in combos:
        lists=[valid[dt] for dt in combo]
        if any(not lst for lst in lists):
            continue
        for coords in itertools.product(*lists):
            if len(set(coords))<3:
                continue
            specialty=dict(zip(combo,coords))
            res=build_and_score(cc,specialty)
            evals+=1
            if res is None:
                continue
            total, placements=res
            if total>best_total:
                best_total=total
                best_cc=cc
                best_specialty=specialty
                best_placements=placements

end=time.time()
print('evals',evals,'time',end-start)
print('best_total',best_total,'cc',best_cc,'specialty',{k.name:v for k,v in best_specialty.items()})
print('placements_count',len(best_placements))

# compute per-type bonuses
_, per=adj_calc.calculate_total_adjacency(best_placements)
bonuses={}
for k,res in per.items():
    name=k.split('@',1)[0]
    bonuses[name]=bonuses.get(name,0)+res.total_bonus

print('bonuses',bonuses)

# output structure
placements_out={}
count_by_name={}
for (x,y),dt in best_placements.items():
    if dt==DistrictType.CITY_CENTER:
        continue
    name=dt.name
    count_by_name[name]=count_by_name.get(name,0)+1
    key=name if count_by_name[name]==1 else f"{name}_{count_by_name[name]}"
    placements_out[key]=[x,y]

sol={
    'city_center':[best_cc[0],best_cc[1]],
    'placements':placements_out,
    'adjacency_bonuses':bonuses,
    'total_adjacency':best_total,
}
print(json.dumps(sol,indent=2))
