import sqlite3, sys, itertools, time, json
sys.path.insert(0,'/skills/civ6lib/scripts')
from placement_rules import Tile, DistrictType, get_placement_rules
from adjacency_rules import get_adjacency_calculator
from hex_utils import get_tiles_in_range, hex_distance, get_neighbor_at_direction

SCENARIO='/data/scenario_3/scenario.json'
MAP='/data/maps/e2e_test_case_0.Civ6Map'
POP=9

# ------------------ map parsing ------------------
conn=sqlite3.connect(MAP)
cur=conn.cursor()
W,H=cur.execute('SELECT Width,Height FROM Map WHERE ID="Default"').fetchone()
plots=cur.execute('SELECT ID,TerrainType FROM Plots').fetchall()
feat=dict(cur.execute('SELECT ID,FeatureType FROM PlotFeatures').fetchall())
res_tbl=cur.execute('SELECT ID,ResourceType FROM PlotResources').fetchall()
imp_tbl=cur.execute('SELECT ID,ImprovementType FROM PlotImprovements').fetchall()
river3={rid:(ne,w,nw) for rid,ne,w,nw in cur.execute('SELECT ID,IsNEOfRiver,IsWOfRiver,IsNWOfRiver FROM PlotRivers').fetchall()}
conn.close()

xy_to_id={(i%W, i//W):i for i,_ in plots}

resources={}
for rid,rt in res_tbl:
    resources[rid]=rt
improvements={}
for rid,it in imp_tbl:
    improvements[rid]=it

def terrain_name(t):
    if t=='TERRAIN_COAST': return 'COAST'
    if t=='TERRAIN_OCEAN': return 'OCEAN'
    if t=='TERRAIN_GRASS': return 'GRASS'
    if t=='TERRAIN_PLAINS': return 'PLAINS'
    if 'MOUNTAIN' in t: return 'MOUNTAIN'
    return 'UNKNOWN'

def river_edges_for(x,y):
    i=xy_to_id.get((x,y))
    ne,w,nw=river3.get(i,(0,0,0))
    edges=set()
    if ne: edges.add(1)
    if nw: edges.add(2)
    if w: edges.add(3)
    # infer remaining from neighbors
    ex,ey=get_neighbor_at_direction(x,y,0)
    j=xy_to_id.get((ex,ey))
    if j is not None and river3.get(j,(0,0,0))[1]: edges.add(0)
    swx,swy=get_neighbor_at_direction(x,y,4)
    j=xy_to_id.get((swx,swy))
    if j is not None and river3.get(j,(0,0,0))[0]: edges.add(4)
    sex,sey=get_neighbor_at_direction(x,y,5)
    j=xy_to_id.get((sex,sey))
    if j is not None and river3.get(j,(0,0,0))[2]: edges.add(5)
    return sorted(edges)

tiles={}
for rid,terr in plots:
    x,y=rid%W, rid//W
    feature=feat.get(rid)
    terrain=terrain_name(terr)
    tiles[(x,y)] = Tile(
        x=x,y=y,
        terrain=terrain,
        feature=feature,
        is_hills=False,
        is_floodplains=bool(feature and 'FLOODPLAINS' in feature),
        river_edges=river_edges_for(x,y),
        resource=resources.get(rid),
        resource_type=None,
        improvement=improvements.get(rid),
    )

adj_calc=get_adjacency_calculator(tiles)

# city center candidates: any non-water non-mountain tile (allow fissure)
cc_candidates=[xy for xy,t in tiles.items() if (not t.is_water and not t.is_mountain and t.feature!='FEATURE_ICE')]

scored_types=[
    DistrictType.CAMPUS,
    DistrictType.HOLY_SITE,
    DistrictType.THEATER_SQUARE,
    DistrictType.COMMERCIAL_HUB,
    DistrictType.HARBOR,
    DistrictType.INDUSTRIAL_ZONE,
]

support_types_priority=[DistrictType.DAM, DistrictType.AQUEDUCT, DistrictType.CANAL, DistrictType.NEIGHBORHOOD]


def build_full_placements(cc, specialty):
    """specialty: dict DistrictType -> (x,y) for up to 3"""
    rules=get_placement_rules(tiles, cc, POP)
    placements={cc: DistrictType.CITY_CENTER}
    # place specialty districts
    for dt,(x,y) in specialty.items():
        res=rules.validate_placement(dt,x,y,placements)
        if not res.valid:
            return None
        placements[(x,y)]=dt

    iz_pos=None
    for (x,y),dt in placements.items():
        if dt==DistrictType.INDUSTRIAL_ZONE:
            iz_pos=(x,y)
            break

    area=[cc]+[p for p in get_tiles_in_range(cc[0],cc[1],3) if p in tiles]

    # initial dense fill
    for (x,y) in area:
        if (x,y) in placements:
            continue
        cand=[]
        if iz_pos and hex_distance(x,y,iz_pos[0],iz_pos[1])==1:
            cand = support_types_priority
        else:
            cand = [DistrictType.NEIGHBORHOOD]
        placed=False
        for dt in cand:
            res=rules.validate_placement(dt,x,y,placements)
            if res.valid:
                placements[(x,y)]=dt
                placed=True
                break
        # else leave empty

    # hill-climb: try removing any non-specialty placement if score improves
    def score(pl):
        return adj_calc.calculate_total_adjacency(pl)[0]

    best_score=score(placements)
    improved=True
    while improved:
        improved=False
        # only consider removing supports (not CC and not specialty)
        removable=[pos for pos,dt in placements.items() if dt in (DistrictType.NEIGHBORHOOD, DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL, DistrictType.SPACEPORT)]
        for pos in removable:
            dt=placements[pos]
            del placements[pos]
            s=score(placements)
            if s>=best_score:
                # keep removal if strictly better or equal? equal removal reduces clutter; keep.
                best_score=s
                improved=True
            else:
                placements[pos]=dt

    return placements, best_score


def extract_solution(cc, placements, total):
    # Convert placements dict to required JSON format (single city)
    # Keep one coord per district name; if multiples (e.g. NEIGHBORHOOD), include with suffix.
    name_to_coords={}
    for (x,y),dt in placements.items():
        if dt==DistrictType.CITY_CENTER:
            continue
        name=dt.name
        if name not in name_to_coords:
            name_to_coords[name]=[x,y]
        else:
            # keep all by making unique keys
            k=2
            while f"{name}_{k}" in name_to_coords:
                k+=1
            name_to_coords[f"{name}_{k}"]=[x,y]

    # adjacency bonuses per district type (aggregate across multiples)
    _, per=adj_calc.calculate_total_adjacency(placements)
    bonuses={}
    for k,res in per.items():
        dt_name=k.split('@',1)[0]
        bonuses[dt_name]=bonuses.get(dt_name,0)+res.total_bonus

    return {
        'city_center':[cc[0],cc[1]],
        'placements': name_to_coords,
        'adjacency_bonuses': bonuses,
        'total_adjacency': total,
    }

start=time.time()
best=None
best_meta=None

for cc in cc_candidates:
    rules=get_placement_rules(tiles, cc, POP)
    base={(cc[0],cc[1]): DistrictType.CITY_CENTER}
    area=[cc]+[p for p in get_tiles_in_range(cc[0],cc[1],3) if p in tiles]

    valid={}
    for dt in scored_types:
        valid[dt]=[]
        for (x,y) in area:
            r=rules.validate_placement(dt,x,y,base)
            if r.valid:
                valid[dt].append((x,y))

    # try all 3-district combos
    for combo in itertools.combinations(scored_types,3):
        # quick skip if any dt has no valid tiles
        if any(not valid[dt] for dt in combo):
            continue
        for coords in itertools.product(*[valid[dt] for dt in combo]):
            if len(set(coords))<3:
                continue
            specialty=dict(zip(combo,coords))
            built=build_full_placements(cc,specialty)
            if built is None:
                continue
            placements,score=built
            if best is None or score>best:
                best=score
                best_meta=(cc,specialty,placements)

end=time.time()
print('searched cc',len(cc_candidates),'best',best,'time',end-start)
cc,specialty,placements=best_meta
sol=extract_solution(cc,placements,best)
print('best cc',cc)
print('specialty', {k.name:v for k,v in specialty.items()})
print('placements count',len(placements))
print('bonuses',sol['adjacency_bonuses'])
print('total',sol['total_adjacency'])
print(json.dumps(sol,indent=2)[:1200])
PY", "security_risk": "MEDIUM", "summary": "Run brute-force search for best city center and district layout"}

