        x=x,y=y,
        terrain=terrain,
        feature=feature,
        is_hills=False,
        is_floodplains=bool(feature and 'FLOODPLAINS' in feature),
        river_edges=river_edges_for(x,y),
        resource=resources.get(rid),
        resource_type=None,
        improvement=improvements.get(rid),
    )

