support_types_priority=[DistrictType.DAM, DistrictType.AQUEDUCT, DistrictType.CANAL, DistrictType.NEIGHBORHOOD]


def build_full_placements(cc, specialty):
    """specialty: dict DistrictType -> (x,y) for up to 3"""
    rules=get_placement_rules(tiles, cc, POP)
    placements={cc: DistrictType.CITY_CENTER}
    # place specialty districts
    for dt,(x,y) in specialty.items():
        res=rules.validate_placement(dt,x,y,placements)
        if not res.valid:
            return None
        placements[(x,y)]=dt

    iz_pos=None
    for (x,y),dt in placements.items():
        if dt==DistrictType.INDUSTRIAL_ZONE:
            iz_pos=(x,y)
            break

    area=[cc]+[p for p in get_tiles_in_range(cc[0],cc[1],3) if p in tiles]

    # initial dense fill
    for (x,y) in area:
        if (x,y) in placements:
            continue
        cand=[]
        if iz_pos and hex_distance(x,y,iz_pos[0],iz_pos[1])==1:
            cand = support_types_priority
        else:
            cand = [DistrictType.NEIGHBORHOOD]
        placed=False
        for dt in cand:
            res=rules.validate_placement(dt,x,y,placements)
            if res.valid:
                placements[(x,y)]=dt
                placed=True
                break
        # else leave empty

    # hill-climb: try removing any non-specialty placement if score improves
    def score(pl):
        return adj_calc.calculate_total_adjacency(pl)[0]

    best_score=score(placements)
    improved=True
    while improved:
        improved=False
        # only consider removing supports (not CC and not specialty)
        removable=[pos for pos,dt in placements.items() if dt in (DistrictType.NEIGHBORHOOD, DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL, DistrictType.SPACEPORT)]
        for pos in removable:
            dt=placements[pos]
            del placements[pos]
            s=score(placements)
            if s>=best_score:
                # keep removal if strictly better or equal? equal removal reduces clutter; keep.
                best_score=s
                improved=True
            else:
                placements[pos]=dt

    return placements, best_score


def extract_solution(cc, placements, total):
    # Convert placements dict to required JSON format (single city)
    # Keep one coord per district name; if multiples (e.g. NEIGHBORHOOD), include with suffix.
    name_to_coords={}
    for (x,y),dt in placements.items():
        if dt==DistrictType.CITY_CENTER:
            continue
        name=dt.name
        if name not in name_to_coords:
            name_to_coords[name]=[x,y]
        else:
            # keep all by making unique keys
            k=2
            while f"{name}_{k}" in name_to_coords:
                k+=1
            name_to_coords[f"{name}_{k}"]=[x,y]

    # adjacency bonuses per district type (aggregate across multiples)
    _, per=adj_calc.calculate_total_adjacency(placements)
    bonuses={}
    for k,res in per.items():
        dt_name=k.split('@',1)[0]
        bonuses[dt_name]=bonuses.get(dt_name,0)+res.total_bonus

    return {
        'city_center':[cc[0],cc[1]],
        'placements': name_to_coords,
        'adjacency_bonuses': bonuses,
        'total_adjacency': total,
    }

start=time.time()
best=None
best_meta=None

for cc in cc_candidates:
    rules=get_placement_rules(tiles, cc, POP)
    base={(cc[0],cc[1]): DistrictType.CITY_CENTER}
    area=[cc]+[p for p in get_tiles_in_range(cc[0],cc[1],3) if p in tiles]

    valid={}
    for dt in scored_types:
        valid[dt]=[]
        for (x,y) in area:
            r=rules.validate_placement(dt,x,y,base)
            if r.valid:
                valid[dt].append((x,y))

    # try all 3-district combos
    for combo in itertools.combinations(scored_types,3):
        # quick skip if any dt has no valid tiles
        if any(not valid[dt] for dt in combo):
            continue
        for coords in itertools.product(*[valid[dt] for dt in combo]):
            if len(set(coords))<3:
                continue
            specialty=dict(zip(combo,coords))
            built=build_full_placements(cc,specialty)
            if built is None:
                continue
            placements,score=built
            if best is None or score>best:
                best=score
                best_meta=(cc,specialty,placements)

end=time.time()
print('searched cc',len(cc_candidates),'best',best,'time',end-start)
cc,specialty,placements=best_meta
sol=extract_solution(cc,placements,best)
print('best cc',cc)
print('specialty', {k.name:v for k,v in specialty.items()})
print('placements count',len(placements))
print('bonuses',sol['adjacency_bonuses'])
print('total',sol['total_adjacency'])
print(json.dumps(sol,indent=2)[:1200])
