import sqlite3, sys, itertools, time, json
sys.path.insert(0,'/skills/civ6lib/scripts')
from placement_rules import Tile, DistrictType, get_placement_rules
from adjacency_rules import get_adjacency_calculator
from hex_utils import get_tiles_in_range, hex_distance, get_neighbor_at_direction, get_neighbors

MAP='/data/maps/e2e_test_case_0.Civ6Map'
POP=9
